/* ============ rooms: each enterable building gets a room in the strip; the door mat takes you back out ============ */
ROOMS = [], ROOM = {};
makeRoom = function makeRoom(o) { const i = o.slot ?? ROOMS.length, x0 = RX0 + 2 + (i % 8) * 16, y0 = 1 + (i >> 3) * 12, r = { ...o, x0, y0, slot: i };
  r.door = [x0 + (o.w >> 1), y0 + o.h]; r.entry = [r.door[0], r.door[1] - 1];
  rect(x0, y0, x0 + o.w - 1, y0 + o.h - 1, (x, y) => { const wall = y < y0 + 2; G[y][x] = wall ? 9 : 8; block[y][x] = wall ? 1 : 0; });
  G[r.door[1]][r.door[0]] = 11; block[r.door[1]][r.door[0]] = 0;
  ROOMS.push(r); if (o.key) ROOM[o.key] = r; return r; }
sceneOf = c => ROOMS.find(r => c[0] >= r.x0 && c[0] < r.x0 + r.w && c[1] >= r.y0 && c[1] <= r.y0 + r.h) || null;

/* ============ grass autotile from the Maeve sheet ============ */
ga = (() => { const c = mk(S.grass.width, S.grass.height), g = c.getContext('2d'); g.drawImage(S.grass, 0, 0); return g.getImageData(0, 0, c.width, c.height); })();
alphaAt = (x, y) => ga.data[(y * ga.width + x) * 4 + 3] > 0 ? 1 : 0;
qStats = function qStats(tx, ty, q) { const fx = q & 1, fy = q >> 1, px = (u, v) => alphaAt(tx * 16 + (fx ? 15 - u : u), ty * 16 + (fy ? 15 - v : v));
  let eH = 0, eV = 0, co = 0, core = 0;
  for (let i = 3; i < 8; i++) for (let j = 0; j < 2; j++) { eH += 1 - px(i, j); eV += 1 - px(j, i); }
  for (let i = 0; i < 2; i++) for (let j = 0; j < 2; j++) co += 1 - px(i, j);
  for (let i = 3; i < 8; i++) for (let j = 3; j < 8; j++) core += 1 - px(i, j);
  return [eH / 10, eV / 10, co / 4, core / 25]; }
WANT = { full: [0, 0, 0, 0], outer: [1, 1, 1, 0], h: [1, 0, .6, 0], v: [0, 1, .6, 0], inner: [0, 0, 1, 0] }, QPICK = {};
for (const [k, w] of Object.entries(WANT)) for (let q = 0; q < 4; q++) { let best = 1e9, at = null;
  for (let ty = 0; ty < 4; ty++) for (let tx = 0; tx < 12; tx++) { const s = qStats(tx, ty, q), d = s.reduce((a, v, i) => a + (v - w[i]) ** 2 * (i === 3 ? 4 : 1), 0); if (d < best) { best = d; at = [tx, ty]; } }
  QPICK[k + q] = at; }
grassAt = (x, y) => x < 0 || y < 0 || x >= VC || y >= VR ? true : G[y][x] === 1 || G[y][x] === 6;

/* ============ Maeve houses, repainted per lot ============ */
hexRGB = h => [1, 3, 5].map(i => parseInt(h.slice(i, i + 2), 16));
paint = function paint(src, roof, wall) {
  const c = mk(src.width, src.height), g = c.getContext('2d'); g.drawImage(src, 0, 0);
  if (!roof && !wall) return c;
  const d = g.getImageData(0, 0, c.width, c.height), p = d.data, eave = c.height - 37, R0 = roof && hexRGB(roof), W0 = wall && hexRGB(wall);
  for (let i = 0; i < p.length; i += 4) { if (!p[i + 3]) continue; const r = p[i], gg = p[i + 1], b = p[i + 2], y = (i / 4 / c.width) | 0, l = (r + gg + b) / 3;
    if (R0 && y < eave && r > gg * 1.5 && r > b * 1.8 && r > 60) { const f = Math.min(1.45, l / 92); p[i] = R0[0] * f; p[i + 1] = R0[1] * f; p[i + 2] = R0[2] * f; }
    else if (W0 && r > 190 && gg > 150 && b > 120 && r - b < 90) { const f = l / 196; p[i] = Math.min(255, W0[0] * f); p[i + 1] = Math.min(255, W0[1] * f); p[i + 2] = Math.min(255, W0[2] * f); } }
  g.putImageData(d, 0, 0); return c; }
cottageRaw = (() => { const c = mk(72, 95); c.getContext('2d').drawImage(S.house, 148, 3, 72, 95, 0, 0, 72, 95); return c; })();
// the big house: two storeys, two chimneys, a balcony, a porch with lamps, flower boxes and bushes (80×126 vs the 72×95 starter)
bigRaw = (() => { const W = 80, H = 126, c = mk(W, H), g = c.getContext('2d'), h = S.house, r = (x, y, w, hh, col) => { g.fillStyle = col; g.fillRect(x, y, w, hh); };
  const bush = (x, y) => { r(x + 3, y, 8, 1, O); r(x + 1, y + 1, 12, 1, O); r(x, y + 2, 14, 8, O); r(x + 1, y + 10, 12, 1, O);
    r(x + 3, y + 1, 8, 1, '#4f9f3f'); r(x + 1, y + 2, 12, 8, '#3f8f3a'); r(x + 2, y + 2, 9, 3, '#6cc04a'); r(x + 4, y + 1, 4, 1, '#8fd860'); r(x + 3, y + 5, 2, 2, '#ff8fbf'); r(x + 9, y + 4, 2, 2, '#fff1a8'); r(x + 6, y + 7, 2, 2, '#ff8fbf'); };
  g.drawImage(h, 90, 64, 13, 30, 16, 4, 13, 30); g.drawImage(h, 90, 64, 13, 30, 52, 0, 13, 30);                 // two chimneys
  g.drawImage(h, 4, 3, 72, 61, 4, 8, 72, 61);                                                                    // roof + gable
  g.drawImage(h, 97, 8, 14, 13, 33, 46, 14, 13);                                                                 // round attic window
  g.drawImage(h, 4, 63, 72, 25, 4, 69, 72, 25);                                                                  // upper floor
  g.drawImage(h, 81, 8, 14, 13, 16, 73, 14, 13); g.drawImage(h, 81, 8, 14, 13, 50, 73, 14, 13); g.drawImage(h, 97, 33, 14, 13, 33, 73, 14, 13);
  r(10, 87, 60, 2, O); r(10, 92, 60, 2, O); for (let x = 10; x <= 68; x += 5) r(x, 87, 2, 7, O);              // balcony rail
  r(11, 88, 58, 1, '#e0a76c'); for (let x = 11; x <= 66; x += 5) r(x, 89, 1, 3, '#c98b54');
  g.drawImage(h, 4, 63, 72, 26, 4, 95, 72, 26); r(8, 94, 64, 2, O);                                              // ground floor + beam
  g.drawImage(h, 97, 33, 14, 13, 14, 99, 14, 13); g.drawImage(h, 97, 33, 14, 13, 52, 99, 14, 13);                // flower windows
  for (const x of [13, 51]) { r(x, 112, 16, 4, O); r(x + 1, 113, 14, 2, '#a8643a'); r(x + 2, 111, 2, 1, '#ff8fbf'); r(x + 7, 111, 2, 1, '#fff1a8'); r(x + 12, 111, 2, 1, '#ff8fbf'); }
  g.drawImage(h, 129, 3, 14, 23, 33, 98, 14, 23);                                                                // front door
  r(29, 94, 22, 4, O); r(30, 95, 20, 2, '#8a5a3c'); r(30, 95, 20, 1, '#b97a45');                               // porch roof
  for (const x of [28, 49]) { r(x, 101, 3, 6, O); r(x + 1, 102, 1, 4, '#ffd23f'); }                              // porch lamps
  g.drawImage(h, 113, 42, 16, 7, 32, 119, 16, 7);                                                                // step
  bush(0, 114); bush(66, 114); return c; })();
houseCache = {};
